class Solution {
public:
    int distributeCandies(vector<int>& candyType) {
        unordered_set<int> uniqueTypes(candyType.begin(), candyType.end());
        return min((int)uniqueTypes.size(), (int)candyType.size() / 2);
    }
};

class Solution {
    public int distributeCandies(int[] candyType) {
        Set<Integer> unique = new HashSet<>();
        for (int c : candyType) unique.add(c);
        return Math.min(unique.size(), candyType.length / 2);
    }
}

var distributeCandies = function(candyType) {
    const unique = new Set(candyType);
    return Math.min(unique.size, Math.floor(candyType.length / 2));
};
